// @i-know-the-amp-plugin-api-is-wip-and-very-experimental-right-now
// (The line above is only for older Amp releases, which wanted it first.)
// agent-monitor-hook-plugin v1
// Generated by agent-monitor (am): reports this Amp's threads to the am
// dashboard by running am-hook with a Claude-style JSON payload on stdin.
// `am hooks install --agent amp` rewrites this file and
// `am hooks uninstall --agent amp` deletes it. Don't edit it by hand.
// Amp loads plugins from ~/.config/amp/plugins/ at startup (not with
// PLUGINS=off; older releases needed PLUGINS=all).
//
// Plain JavaScript on purpose (no type imports), so it needs nothing from
// `@ampcode/plugin` at runtime.

import { spawn } from "node:child_process";

export const description = "Reports Amp thread status to the agent-monitor (am) dashboard.";

// am-hook's argv; the event name goes last. An empty --worktree makes am-hook
// use the payload's cwd. As a shell command:
// __AM_HOOK_COMMAND__
const HOOK = [__AM_HOOK_ARGV__];
const TIMEOUT_MS = 5000;
const MAX_QUEUED = 200;
const MAX_THREADS = 128;
// The only environment am-hook gets: no API keys or anything else of Amp's.
const ENV_KEYS = ["HOME", "PATH", "USER", "LOGNAME", "TMPDIR", "LANG", "AM_DATA_DIR", "AM_HOOK_CAPTURE"];

// One hook at a time, in order, so a Stop can't overtake the PostToolUse
// before it. Never awaited by Amp.
let chain = Promise.resolve();
let queued = 0;

function hookEnv() {
  const env = {};
  for (const k of ENV_KEYS) if (typeof process.env[k] === "string") env[k] = process.env[k];
  return env;
}

function runHook(event, payload) {
  return new Promise((resolve) => {
    let settled = false;
    let timer = null;
    const done = () => {
      if (settled) return;
      settled = true;
      if (timer) clearTimeout(timer);
      resolve();
    };
    let child;
    try {
      child = spawn(HOOK[0], [...HOOK.slice(1), event], { stdio: ["pipe", "ignore", "ignore"], detached: true, env: hookEnv() });
    } catch (_) {
      return done();
    }
    child.on("error", done);
    child.on("close", done);
    timer = setTimeout(() => {
      try { child.kill("SIGKILL"); } catch (_) {}
      done();
    }, TIMEOUT_MS);
    child.unref();
    try {
      child.stdin.on("error", () => {});
      child.stdin.end(JSON.stringify(payload));
    } catch (_) {}
  });
}

function send(event, payload) {
  if (queued >= MAX_QUEUED) return;
  queued += 1;
  chain = chain
    .then(() => runHook(event, payload))
    .catch(() => {})
    .then(() => { queued -= 1; });
}

function str(v) {
  return typeof v === "string" && v.trim() ? v.trim() : null;
}

function clip(v) {
  return str(v) ? v.slice(0, 500) : undefined;
}

// Amp's thread states, folded to: running, waiting (a tool approval or
// other input), idle, error.
function stateOf(value) {
  const raw = typeof value === "string" ? value : value && (str(value.state) || str(value.value));
  switch (String(raw || "").toLowerCase().replace(/_/g, "-")) {
    case "running": case "thinking": case "working": return "running";
    case "awaiting-approval": case "awaiting-input": case "needs-input": case "blocked": return "waiting";
    case "idle": case "done": case "complete": case "completed": return "idle";
    case "error": case "failed": return "error";
    default: return null;
  }
}

function outcomeOf(status) {
  switch (String(status || "done").toLowerCase()) {
    case "error": case "failed": return "error";
    default: return "done"; // done, cancelled
  }
}

export default function (amp) {
  // Per thread: whether a turn is open (one Stop per turn: a second would
  // turn done into idle), whether a state change opened it rather than
  // agent.start (then idle ends it: agent.end may never come here), whether
  // it waits on the user, the turn's outcome once agent.end reported it, the
  // last state seen and the last tool.
  const threads = new Map();
  const subscriptions = new Map();

  const toPath = (uri) => {
    if (!uri) return null;
    try {
      const p = amp.helpers && amp.helpers.filePathFromURI && amp.helpers.filePathFromURI(uri);
      if (str(p)) return p;
    } catch (_) {}
    try {
      const u = new URL(String(uri));
      if (u.protocol === "file:") return decodeURIComponent(u.pathname);
    } catch (_) {}
    return str(uri) && String(uri).startsWith("/") ? String(uri) : null;
  };
  // The plugin process may run in another directory than the thread, so the
  // workspace root comes first, then the directory Amp was started from.
  let workspace = null;
  try { workspace = toPath(amp.system && amp.system.workspaceRoot); } catch (_) {}
  const cwd = () => workspace || str(process.env.PWD) || process.cwd();

  const state = (id) => {
    let t = threads.get(id);
    if (!t) {
      t = { turn: false, byState: false, waiting: false, pending: null, last: null, tool: null };
      threads.set(id, t);
      if (threads.size > MAX_THREADS) {
        const old = threads.keys().next().value;
        threads.delete(old);
        const sub = subscriptions.get(old);
        subscriptions.delete(old);
        try { sub && sub.unsubscribe && sub.unsubscribe(); } catch (_) {}
      }
    }
    return t;
  };

  const emit = (id, event, extra) => {
    send(event, { session_id: id, cwd: cwd(), hook_event_name: event, ...extra });
  };

  // `byAgent`: agent.start opened (or took over) the turn, so agent.end
  // will close it.
  const begin = (id, byAgent) => {
    const t = state(id);
    t.pending = null;
    t.last = "running";
    if (t.turn) {
      if (byAgent) t.byState = false;
      return;
    }
    t.turn = true;
    t.byState = !byAgent;
    emit(id, "UserPromptSubmit");
  };

  const resume = (id) => {
    const t = state(id);
    if (!t.waiting) return;
    t.waiting = false;
    emit(id, "PostToolUse");
  };

  const finish = (id, outcome) => {
    const t = state(id);
    t.pending = null;
    if (!t.turn) return;
    t.turn = false;
    t.byState = false;
    // Stop keeps a waiting session waiting; leave it first.
    resume(id);
    emit(id, outcome === "error" ? "StopFailure" : "Stop");
  };

  const onState = (id, value) => {
    const s = stateOf(value);
    if (!s) return;
    const t = state(id);
    t.last = s;
    if (s === "running") {
      resume(id);
      if (!t.turn) begin(id);
    } else if (s === "waiting") {
      if (!t.turn) begin(id);
      if (t.waiting) return;
      t.waiting = true;
      emit(id, "PermissionRequest", t.tool ? { tool_name: t.tool } : {});
    } else if (s === "error") {
      finish(id, "error");
    } else if (t.pending || (t.turn && t.byState)) {
      // idle after agent.end, or ending a turn no agent.start opened (another
      // plugin's thread.append, another Amp client); an idle before
      // agent.end otherwise waits for it.
      finish(id, t.pending || "done");
    }
  };

  const handleOf = (id, event, ctx) => {
    const own = (x) => (x && str(x.id) === id && x.state ? x : null);
    let h = own(ctx && ctx.thread) || own(event && event.thread);
    if (!h) {
      try { h = amp.threads && amp.threads.get && amp.threads.get(id); } catch (_) { h = null; }
    }
    return h && h.state ? h : null;
  };

  // thread.state is authoritative for waiting and for when a turn is over.
  const watch = (id, event, ctx) => {
    if (subscriptions.has(id)) return true;
    const h = handleOf(id, event, ctx);
    if (!h || !h.state.subscribe) return false;
    try {
      const sub = h.state.subscribe((v) => { try { onState(id, v); } catch (_) {} });
      subscriptions.set(id, sub || {});
      return true;
    } catch (_) {
      return false;
    }
  };

  const threadId = (event, ctx) => str(event && event.thread && event.thread.id) || str(ctx && ctx.thread && ctx.thread.id);

  const guard = (fn) => async (event, ctx) => {
    try { fn(event || {}, ctx); } catch (_) {}
  };

  // session.start also fires when the user opens or switches to a thread,
  // so only a thread new to this process gets SessionStart (it means idle,
  // and would clear a running or done thread).
  amp.on("session.start", guard((event, ctx) => {
    const id = threadId(event, ctx);
    if (!id) return;
    const seen = threads.has(id);
    state(id);
    if (!seen) emit(id, "SessionStart");
    watch(id, event, ctx);
  }));

  amp.on("agent.start", guard((event, ctx) => {
    const id = threadId(event, ctx);
    if (!id) return;
    // Subscribe first: a subscription that replays the current (pre-turn)
    // state can't then mark the new turn idle.
    watch(id, event, ctx);
    begin(id, true);
  }));

  amp.on("agent.end", guard((event, ctx) => {
    const id = threadId(event, ctx);
    if (!id || !threads.has(id)) return;
    const t = state(id);
    const outcome = outcomeOf(event.status);
    if (!watch(id, event, ctx) || t.last === "idle" || t.last === "error") return finish(id, outcome);
    // Wait for thread.state to settle (another plugin may continue the turn).
    t.pending = outcome;
    const h = handleOf(id, event, ctx);
    if (!h || !h.state.get) return;
    try {
      Promise.resolve(h.state.get()).then((v) => { try { if (t.pending) onState(id, v); } catch (_) {} }, () => {});
    } catch (_) {}
  }));

  // Tool events of threads am hasn't seen start (e.g. a subagent's own
  // thread) are left out, so they never become sessions of their own.
  const toolEvent = (name) => (event) => {
    const id = str(event.thread && event.thread.id);
    if (!id || !threads.has(id)) return;
    const t = state(id);
    const tool = str(event.tool) || "unknown";
    if (name === "PreToolUse") {
      t.tool = tool;
      if (!t.turn) begin(id);
    } else if (!t.turn) {
      return; // a result arriving after the turn ended
    }
    emit(id, name, { tool_name: tool, tool_input: toolInput(event) });
  };

  const toolInput = (event) => {
    const input = event.input && typeof event.input === "object" ? event.input : {};
    let command = null;
    try {
      const sh = amp.helpers && amp.helpers.shellCommandFromToolCall && amp.helpers.shellCommandFromToolCall(event);
      command = sh && str(sh.command);
    } catch (_) {}
    const out = {
      command: clip(command || input.cmd || input.command),
      description: clip(input.description),
      file_path: clip(input.path || input.filePath || input.file_path),
      pattern: clip(input.pattern || input.filePattern),
      url: clip(input.url),
      query: clip(input.query),
    };
    for (const k of Object.keys(out)) if (out[k] === undefined) delete out[k];
    return Object.keys(out).length ? out : undefined;
  };

  // A request handler: Amp needs a result, and `allow` never overrides
  // another plugin's decision.
  const preTool = toolEvent("PreToolUse");
  amp.on("tool.call", async (event) => {
    try { preTool(event || {}); } catch (_) {}
    return { action: "allow" };
  });
  amp.on("tool.result", guard(toolEvent("PostToolUse")));
}
